package main

import (
	"flag"
	"fmt"
	"os"
	"strings"
	"text/template"

	"github.com/iancoleman/strcase"
	"github.com/sirupsen/logrus"
)

//nolint:lll
const cmdTemplate = `package main

// Code generated by internal/cmd-gen; DO NOT EDIT.

import (
	"context"
	"strconv"

	"github.com/sirupsen/logrus"
	"github.com/spf13/cobra"

	{{ splitBefore .Import }} "{{ splitAfter .Import }}"
	ctrlclient "sigs.k8s.io/controller-runtime/pkg/client"
)

var (
	{{ .Type }}Cmd = &cobra.Command{
		Use:   "{{ .Type }} [-n 1000] [--kubeconfig /path/to/kube/config]",
		Short: "scale {{ .Type }}",
		Run:   scale{{ toCamel .Type }},
		Hidden: true,
	}
	p{{ .Type }} string
)


func scale{{ toCamel .Type }}(cmd *cobra.Command, args []string) {
	req := cmd.Root().Flag("number").Value.String()
	logrus.Infof("number value from root cmd: (%v)\n", req)
	logrus.Traceln("trace starting")
	logrus.Debugln("debug starting")
	num, err := strconv.Atoi(req)
	if err != nil {
		logrus.Fatal(err)
	}
	k := &KScalerConfig{
			Scale: Scaler{
				Resource:  "{{ toLower .Type }}",
				Request:   num,
			},
	}
	logrus.Printf("k.Scale: (%#v)\n", k.Scale)
	logrus.Printf("request: %v\n", k.Scale.Request)
	logrus.Printf("[scale{{ toCamel .Type }}] attempting to create (%v) resources of type {{ .Type }}\n", k.Scale.Request)
	
	if err := Parser(k); err != nil {
		cmd.Println("")
		cmd.Println("[scale{{ toCamel .Type }}] error encountered")
		logrus.Fatalf(err.Error())
	}
}

func cleanup{{ toCamel .Type }}(ctx context.Context, cli ctrlclient.Client) error {
	logrus.Infof("attempting to cleanup all kscaler created {{ .Type }}s\n")

	{{ if eq .Type "namespace" }}
	objList := &corev1.NamespaceList{}
	err := cli.List(ctx, objList, ctrlclient.MatchingLabels{"created-by": DefaultName})
	deletedObjCount := 0
	for _, obj := range objList.Items {
		err = cli.Delete(ctx, &obj)
		if err != nil {
			logrus.Errorf("[cleanup] error encountered while cleaning up kscaler created {{ toCamel .Type }}s: %s\n", err)
			continue
		}
		deletedObjCount++
	}
	logrus.Infof("[cleanup] cleaned up %d/%d kscaler {{ toCamel .Type }}s\n", deletedObjCount, len(objList.Items))
	{{ else }}
	obj := &{{ splitBefore .Import }}.{{ toCamel .Type }}{}
	opts := []ctrlclient.DeleteAllOfOption{ctrlclient.InNamespace(DefaultNamespace), ctrlclient.MatchingLabels{"created-by": DefaultName}}
	err := cli.DeleteAllOf(ctx, obj, opts...)
	if err != nil {
		logrus.Errorf("[cleanup] error encountered while cleaning up kscaler created {{ toCamel .Type }}s: %s\n", err)
		return err
	}
	logrus.Infof("[cleanup] cleaned up all kscaler {{ toCamel .Type }}s\n")
	{{ end }}
	return nil
}
`

type parameters struct {
	Type         string
	Import       string
	HasNamespace bool
}

// cmd-gen creates common function for Kubernetes object wrappers.
func main() {
	var parameters parameters

	flag.StringVar(&parameters.Type, "type", "", "type to generate")
	flag.BoolVar(&parameters.HasNamespace, "hasNamespace", true, "type uses namespace")
	flag.StringVar(&parameters.Import, "import", "", "name of imported package")

	flag.Parse()

	switch parameters.Import {
	case "appsv1":
		parameters.Import = "appsv1,k8s.io/api/apps/v1"
	case "corev1":
		parameters.Import = "corev1,k8s.io/api/core/v1"
	case "rbacv1":
		parameters.Import = "rbacv1,k8s.io/api/rbac/v1"
	default:
		logrus.Fatalf("unknown import %s", parameters.Import)
	}
	funcMap := template.FuncMap{
		"toLower": strings.ToLower,
		"toCamel": func(s string) string {
			return strcase.ToCamel(s)
		},
		"formatImport": func(s string) string { return strings.Replace(s, ",", " ", -1) },
		"splitBefore":  func(s string) string { return strings.Split(s, ",")[0] },
		"splitAfter":   func(s string) string { return strings.Split(s, ",")[1] },
	}

	tmpl, err := template.New("resource").Funcs(funcMap).Parse(cmdTemplate)
	if err != nil {
		panic(err)
	}

	outputName := fmt.Sprintf("%s.generated.go", strings.ToLower(parameters.Type))

	output, err := os.Create(outputName)
	if err != nil {
		panic(err)
	}

	defer func() {
		if err := output.Close(); err != nil {
			panic(err)
		}
	}()

	if err := tmpl.Execute(output, parameters); err != nil {
		panic(err)
	}
}
